public final class GeneratedRuleBatch44Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static void check(boolean b,String why){GeneratedRuleBatch8Test.check(b,why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static AttackDefinition snack(String id){return BundledCombatData.attack(GeneratedRuleBatch8Test.entry(id).getAsJsonArray("attacks").get(0).getAsJsonObject(),EffectRegistry.standard());}
    static EffectDefinition effect(){return snack("me5-5_en_061").effectProgram().triggers().getFirst().effects().getFirst();}
    static ServerMatch fixture(AttackDefinition attack){var m=GeneratedRuleBatch42Test.fixture(attack,false,false,List.of());var e=GeneratedRuleBatch13Test.hand(m,A,"energy");m.attachEnergyByEffect(A,A,EffectSourceZone.HAND,e.instanceId(),A,m.activePokemonView(A).pokemonId());return m;}
    static List<CardInstance> top(ServerMatch m,int n){var deck=m.privateView(A).deck();return List.copyOf(deck.subList(Math.max(0,deck.size()-n),deck.size()));}
    static Set<UUID> ids(Collection<CardInstance> cards){return new LinkedHashSet<>(cards.stream().map(CardInstance::instanceId).toList());}
    /** Controlled state transition isolates the final stale-card check; normal player actions are locked during a prompt. */
    @SuppressWarnings("unchecked") static void moveStaleCard(ServerMatch m,CardInstance card){try{var f=ServerMatch.class.getDeclaredField("players");f.setAccessible(true);Object state=((Map<?,?>)f.get(m)).get(A);var discard=state.getClass().getDeclaredField("discard");var hand=state.getClass().getDeclaredField("hand");discard.setAccessible(true);hand.setAccessible(true);check(((List<CardInstance>)discard.get(state)).remove(card),"Stale card was not in discard");((List<CardInstance>)hand.get(state)).add(card);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    static void assertRejectedAtomic(ServerMatch m,Runnable action){var a=m.privateView(A);var b=m.privateView(B);var random=m.randomTranscript();reject(action);check(a.equals(m.privateView(A))&&b.equals(m.privateView(B))&&random.equals(m.randomTranscript()),"Rejected submission changed zones or RNG");}
    static CardInstance choose(ServerMatch m){var p=m.effectCardPrompt(A);var selected=p.candidates().getFirst();m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(selected.instanceId()));var reveal=m.effectCardReveal();check(reveal!=null&&reveal.cardIds().equals(List.of(selected.definitionId()))&&reveal.confirmingPlayer().equals(B),"Selected public card not shown to opponent");check(m.privateView(A).discard().contains(selected)&&!m.privateView(A).hand().contains(selected),"Recovered card moved before reveal acknowledgement");assertRejectedAtomic(m,()->m.acknowledgeEffectReveal(A,reveal.id()));assertRejectedAtomic(m,()->m.acknowledgeEffectReveal(B,UUID.randomUUID()));m.acknowledgeEffectReveal(B,reveal.id());check(m.privateView(A).hand().contains(selected)&&!m.privateView(A).discard().contains(selected),"Acknowledged card was not recovered");return selected;}
    public static void main(String[] args){deckSizes();rejectForeignCards();staleCard();twoWindows();repeatedUses();schema();System.out.println("GeneratedRuleBatch44Test passed: both actual Select a Snack printings with printed Energy cost, discard-before-selection, exact physical top window, empty/short deck, mandatory one-card recovery, public reveal acknowledgement, atomic invalid/stale submissions, independent repeated windows and no shuffle/RNG");}
    static void deckSizes(){for(String id:List.of("me5-5_en_061","me5-5_en_135"))for(int size:List.of(0,1,2,3,5)){
        var attack=snack(id);check(attack.energyCost().equals(Map.of(EnergyType.COLORLESS,1)),"Real printed cost removed");var m=fixture(attack);int trim=m.privateView(A).deck().size()-size;if(trim>0)m.discardTopDeckCardsByEffect(A,A,trim);var before=List.copyOf(m.privateView(A).deck());var window=top(m,3);var old=List.copyOf(m.privateView(A).discard());int hand=m.privateView(A).hand().size(),rng=m.randomTranscript().size();m.attack(A,attack.id());
        if(size==0){check(!m.hasPendingEffectChoice()&&m.privateView(A).hand().size()==hand&&m.privateView(A).discard().equals(old),"Empty deck recovered an old discard card");continue;}
        var p=m.effectCardPrompt(A);check(p!=null&&p.minimum()==1&&p.maximum()==1&&ids(p.candidates()).equals(ids(window)),"Candidates include old discard or omit an actual top card");check(m.privateView(A).discard().containsAll(window)&&m.privateView(A).discard().size()==old.size()+window.size(),"All top cards must be discarded before the choice");check(m.clientView(B).players().stream().filter(x->x.id().equals(A)).findFirst().orElseThrow().discard().containsAll(window),"Opponent cannot see actual discarded cards");check(m.clientView(B).effectSelection()==null,"Opponent received control of the owner's recovery choice");for(int i=0;i<3;i++)check(ids(m.effectCardPrompt(A).candidates()).equals(ids(window)),"Reading prompt re-discarded or widened window");assertRejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of()));var selected=choose(m);check(m.privateView(A).hand().size()==hand+1&&m.privateView(A).discard().size()==old.size()+window.size()-1,"Recovery moved wrong number of cards");check(m.privateView(A).deck().equals(before.subList(0,before.size()-window.size()))&&m.randomTranscript().size()==rng,"Recovery shuffled or changed untouched deck order");check(m.currentPlayer().equals(B)&&!m.hasPendingEffectChoice()&&m.privateView(A).discard().containsAll(window.stream().filter(c->!c.equals(selected)).toList()),"Attack did not finish with the unchosen cards discarded");
    }}
    static void rejectForeignCards(){var attack=snack("me5-5_en_061");var m=fixture(attack);m.discardTopDeckCardsByEffect(A,A,2);var old=List.copyOf(m.privateView(A).discard());m.attack(A,attack.id());var p=m.effectCardPrompt(A);var chosen=p.candidates().getFirst();var foreign=GeneratedRuleBatch13Test.hand(m,B,"plain");for(Runnable r:List.<Runnable>of(()->m.submitEffectCards(B,p.resolutionId(),p.step(),List.of(chosen.instanceId())),()->m.submitEffectCards(A,UUID.randomUUID(),p.step(),List.of(chosen.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step()+1,List.of(chosen.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(old.getFirst().instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(foreign.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(chosen.instanceId(),chosen.instanceId())),()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(chosen.instanceId(),p.candidates().getLast().instanceId()))))assertRejectedAtomic(m,r);check(m.effectCardPrompt(A).equals(p),"Bad request replaced recovery transaction");choose(m);assertRejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(chosen.instanceId())));}
    static void staleCard(){var attack=snack("me5-5_en_061");var m=fixture(attack);m.attack(A,attack.id());var p=m.effectCardPrompt(A);var stale=p.candidates().getFirst();moveStaleCard(m,stale);assertRejectedAtomic(m,()->m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(stale.instanceId())));var live=p.candidates().getLast();m.submitEffectCards(A,p.resolutionId(),p.step(),List.of(live.instanceId()));m.acknowledgeEffectReveal(B,m.effectCardReveal().id());check(m.privateView(A).hand().containsAll(List.of(stale,live)),"Stale rejection destroyed still-valid recovery choice");}
    static void twoWindows(){var json=GeneratedRuleBatch8Test.entry("me5-5_en_061").getAsJsonArray("attacks").get(0).getAsJsonObject().deepCopy();var effects=json.getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects");effects.add(effects.get(0).deepCopy());json.addProperty("id","two-snacks");var attack=BundledCombatData.attack(json,EffectRegistry.standard());var m=fixture(attack);var deck=List.copyOf(m.privateView(A).deck());int rng=m.randomTranscript().size();m.attack(A,attack.id());var first=m.effectCardPrompt(A);var firstWindow=ids(first.candidates());choose(m);var second=m.effectCardPrompt(A);check(second!=null&&second.step()!=first.step()&&Collections.disjoint(firstWindow,ids(second.candidates()))&&ids(second.candidates()).equals(ids(deck.subList(deck.size()-6,deck.size()-3))),"Second lexical step reused first discard window");choose(m);check(m.privateView(A).deck().equals(deck.subList(0,deck.size()-6))&&m.randomTranscript().size()==rng&&!m.hasPendingEffectChoice(),"Two steps did not discard each window exactly once");}
    static void repeatedUses(){var attack=snack("me5-5_en_061");var m=fixture(attack);m.attack(A,attack.id());var first=ids(m.effectCardPrompt(A).candidates());choose(m);m.endTurn(B);var next=ids(top(m,3));m.attack(A,attack.id());check(ids(m.effectCardPrompt(A).candidates()).equals(next)&&Collections.disjoint(first,next),"Later use inherited an old recovery window");choose(m);}
    static void schema(){var actual=GeneratedRuleBatch8Test.entry("me5-5_en_061").getAsJsonArray("attacks").get(0).getAsJsonObject().getAsJsonArray("triggers").get(0).getAsJsonObject().getAsJsonArray("effects").get(0).getAsJsonObject();for(var kv:Map.of("discard_top_count","4","destination","DECK_SHUFFLED","reveal","false","amount","2","minimum","2","target","DECK","source_owner","OPPONENT").entrySet()){var bad=actual.deepCopy();bad.addProperty(kv.getKey(),kv.getValue());reject(()->ZoneSelectionEffect.forProgram(EffectRegistry.standard().parse(bad),true));}for(var trigger:List.of(EffectTrigger.BEFORE_ATTACK,EffectTrigger.ONCE_PER_TURN,EffectTrigger.ON_CARD_PLAYED)){var p=new EffectProgram(List.of(new TriggeredEffects(trigger,List.of(),List.of(effect()))));reject(()->ResumableProgramRules.validate(p,trigger!=EffectTrigger.ON_CARD_PLAYED,trigger));}var m=fixture(snack("me5-5_en_061"));assertRejectedAtomic(m,()->m.openEffectZoneSelection(A,effect(),1));var zero=actual.deepCopy();zero.addProperty("minimum",0);reject(()->ZoneSelectionEffect.forProgram(EffectRegistry.standard().parse(zero),true));}
}
